<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>CWC — Login</title>
<link href="https://cdn.jsdelivr.net/npm/remixicon@3.5.0/fonts/remixicon.css" rel="stylesheet">
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap" rel="stylesheet">
<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html,body{height:100%;font-family:"Inter",sans-serif;overflow:hidden}

.wrap{display:flex;height:100vh;width:100vw}

/* ── LEFT: full image ── */
.img-side{
    flex:1;
    position:relative;
    overflow:hidden;
}
.img-bg{
    position:absolute;inset:0;
    background-image:url("data:image/png;base64,");
    background-size:cover;
    background-position:center;
    background-repeat:no-repeat;
    animation:zoom 20s ease-in-out infinite alternate;
}
@keyframes zoom{0%{transform:scale(1)}100%{transform:scale(1.05)}}

/* subtle right-edge fade into white form */
/* .img-edge{
    position:absolute;inset:0;
    background:linear-gradient(to right,transparent 75%,rgba(255,255,255,.6) 90%,rgba(255,255,255,1) 100%);
} */

/* ── RIGHT: login form ── */
.form-side{
    width:420px;
    flex-shrink:0;
    background:#fff;
    display:flex;
    flex-direction:column;
    justify-content:center;
    padding:52px 44px;
    box-shadow:-24px 0 60px rgba(0,0,0,.10);
}

/* logo area */
.logo-row{
    display:flex;align-items:center;gap:12px;
    margin-bottom:32px;padding-bottom:28px;
    border-bottom:1px solid #f1f5f9;
}
.logo-row img{height:48px;width:auto}
.logo-sep{width:1.5px;height:40px;background:#e2e8f0}
.logo-text h2{font-size:13px;font-weight:800;color:#0f172a;line-height:1.4}
.logo-text p{font-size:10px;color:#94a3b8;font-weight:500;margin-top:2px}

/* heading */
.f-title{font-size:26px;font-weight:900;color:#0f172a;letter-spacing:-.5px;margin-bottom:6px}
.f-sub{font-size:13px;color:#94a3b8;font-weight:400;line-height:1.6;margin-bottom:28px}

/* alerts */
.al{border-radius:10px;padding:11px 14px;font-size:12px;font-weight:500;
    display:flex;align-items:center;gap:8px;margin-bottom:16px}
.al-ok{background:#f0fdf4;border:1px solid #bbf7d0;color:#065f46}
.al-err{background:#fef2f2;border:1px solid #fecaca;color:#991b1b}

/* fields */
.fg{margin-bottom:16px}
.fg label{display:block;font-size:11px;font-weight:700;text-transform:uppercase;
          letter-spacing:.09em;color:#64748b;margin-bottom:7px}
.iw{position:relative;display:flex;align-items:center}
.iw input{
    width:100%;height:50px;
    border:1.5px solid #e2e8f0;border-radius:11px;
    padding:0 15px 0 46px;
    font-size:13.5px;color:#0f172a;background:#f8fafc;
    outline:none;font-family:"Inter",sans-serif;
    transition:all .2s ease;
}
.iw input::placeholder{color:#c1cbd8}
.iw input:focus{border-color:#2563eb;background:#fff;box-shadow:0 0 0 3px rgba(37,99,235,.10)}
.ii{position:absolute;left:14px;font-size:18px;color:#c1cbd8;pointer-events:none;transition:color .2s}
.iw input:focus~.ii{color:#2563eb}
.pw-eye{position:absolute;right:13px;background:none;border:none;
    color:#c1cbd8;font-size:18px;cursor:pointer;padding:0;line-height:1;transition:color .2s}
.pw-eye:hover{color:#2563eb}
.ferr{margin-top:5px;font-size:11px;color:#dc2626;font-weight:500;
      display:flex;align-items:center;gap:4px}

/* meta */
.fmeta{display:flex;align-items:center;justify-content:space-between;margin:6px 0 24px}
.rem{display:flex;align-items:center;gap:8px;font-size:12.5px;
     color:#64748b;font-weight:500;cursor:pointer;user-select:none}
.rem input{width:15px;height:15px;accent-color:#2563eb;cursor:pointer}
.forg{font-size:12px;font-weight:600;color:#2563eb;text-decoration:none;transition:opacity .18s}
.forg:hover{opacity:.7;text-decoration:underline}

/* BLUE submit button */
.btn{
    width:100%;height:52px;
    background:#2563eb;
    color:#fff;border:none;border-radius:11px;
    font-size:14px;font-weight:800;letter-spacing:.04em;
    text-transform:uppercase;cursor:pointer;
    font-family:"Inter",sans-serif;
    display:flex;align-items:center;justify-content:center;gap:10px;
    position:relative;overflow:hidden;
    transition:all .22s ease;
    box-shadow:0 6px 24px rgba(37,99,235,.30);
}
.btn i{font-size:20px}
.btn::before{
    content:"";position:absolute;top:0;left:-100%;
    width:60%;height:100%;
    background:linear-gradient(90deg,transparent,rgba(255,255,255,.15),transparent);
    transition:left .55s ease;
}
.btn:hover::before{left:140%}
.btn:hover{background:#1d4ed8;transform:translateY(-2px);box-shadow:0 12px 32px rgba(37,99,235,.38)}
.btn:active{transform:translateY(0)}

/* trust + footer */
.trust{display:flex;gap:6px;justify-content:center;margin-top:22px}
.tc{display:inline-flex;align-items:center;gap:5px;padding:5px 11px;
    border-radius:20px;border:1px solid #e9eef5;background:#f8fafc;
    font-size:10.5px;font-weight:600;color:#94a3b8}
.tc i{font-size:13px;color:#22c55e}
.pwrd{margin-top:22px;text-align:center;font-size:11px;color:#d1d5db;
      display:flex;align-items:center;justify-content:center;gap:8px}
.pwrd::before,.pwrd::after{content:"";flex:1;height:1px;background:#f1f5f9}

@media(max-width:860px){.img-side{display:none}.form-side{width:100%;padding:48px 28px}}
</style>
</head>
<body>
<div class="wrap">

    <!-- LEFT: CWC Smart Warehouse image -->
    <div class="img-side">
        <div class="img-bg"></div>
        <div class="img-edge"></div>
    </div>

    <!-- RIGHT: login -->
    <div class="form-side">





        @if(session('status'))
        <div class="al al-ok"><i class="ri-checkbox-circle-line"></i> {{ session('status') }}</div>
        @endif
        @if($errors->any())
        <div class="al al-err"><i class="ri-error-warning-line"></i> {{ $errors->first() }}</div>
        @endif

        <form method="POST" action="{{ route('login') }}">
            @csrf

            <div class="fg">
                <label>Email Address</label>
                <div class="iw">
                    <input type="email" name="email" value="{{ old('email') }}"
                           placeholder="Email Address" required autofocus>
                    <i class="ri-mail-line ii"></i>
                </div>
                @error('email')<div class="ferr"><i class="ri-error-warning-fill"></i> {{ $message }}</div>@enderror
            </div>

            <div class="fg">
                <label>Password</label>
                <div class="iw">
                    <input type="password" id="pwInp" name="password"
                           placeholder="••••••••" required style="padding-right:46px">
                    <i class="ri-lock-line ii"></i>
                    <button type="button" class="pw-eye" onclick="tpw()">
                        <i class="ri-eye-off-line" id="pwIco"></i>
                    </button>
                </div>
                @error('password')<div class="ferr"><i class="ri-error-warning-fill"></i> {{ $message }}</div>@enderror
            </div>

            <div class="fmeta">
                <label class="rem">
                    <input type="checkbox" name="remember"> Remember me
                </label>
                <!-- <a href="{{ route('password.request') }}" class="forg">Forgot password?</a> -->
            </div>

            <button type="submit" class="btn">
                <i class="ri-login-box-line"></i>
                Sign In
            </button>
        </form>



        <div class="pwrd">Designed &amp; Developed by RailTel</div>

    </div>
</div>

<script>
function tpw(){
    const i=document.getElementById("pwInp"),ic=document.getElementById("pwIco");
    if(i.type==="password"){i.type="text";ic.className="ri-eye-line"}
    else{i.type="password";ic.className="ri-eye-off-line"}
}
</script>
</body>
</html>

